import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# -------------------------------------------------------------------------
# CUDA kernel (inline extension)
# -------------------------------------------------------------------------
src = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_fp16.h>

template <int BLOCK_SIZE>
__global__ void batchnorm_fp16_forward_kernel(
    const __half* __restrict__ input,
    __half* __restrict__ output,
    const __half* __restrict__ weight,
    const __half* __restrict__ bias,
    const int N,
    const int C,
    const int H,
    const int W,
    const float eps)
{
    // one block per channel
    const int c = blockIdx.x;
    if (c >= C) return;

    const int spatial = H * W;
    const int channel_size = N * spatial;          // total elements per channel

    // ----------- compute mean -------------
    extern __shared__ float sdata[];
    float sum = 0.0f;
    for (int idx = threadIdx.x; idx < channel_size; idx += BLOCK_SIZE) {
        // compute linear index of (n,c,h,w)
        int n = idx / spatial;
        int rem = idx - n * spatial;
        int h = rem / W;
        int w = rem - h * W;
        int offset = ((n * C + c) * H + h) * W + w;
        sum += __half2float(input[offset]);
    }
    sdata[threadIdx.x] = sum;
    __syncthreads();

    // reduction in shared memory
    for (int stride = BLOCK_SIZE / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            sdata[threadIdx.x] += sdata[threadIdx.x + stride];
        }
        __syncthreads();
    }
    const float mean = sdata[0] / static_cast<float>(channel_size);

    // ----------- compute variance ----------
    float var_sum = 0.0f;
    for (int idx = threadIdx.x; idx < channel_size; idx += BLOCK_SIZE) {
        int n = idx / spatial;
        int rem = idx - n * spatial;
        int h = rem / W;
        int w = rem - h * W;
        int offset = ((n * C + c) * H + h) * W + w;
        float val = __half2float(input[offset]);
        float diff = val - mean;
        var_sum += diff * diff;
    }
    sdata[threadIdx.x] = var_sum;
    __syncthreads();

    for (int stride = BLOCK_SIZE / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            sdata[threadIdx.x] += sdata[threadIdx.x + stride];
        }
        __syncthreads();
    }
    const float var = sdata[0] / static_cast<float>(channel_size);
    const float inv_std = rsqrtf(var + eps);

    // load affine parameters (convert to float for computation)
    const float w = __half2float(weight[c]);
    const float b = __half2float(bias[c]);

    // ----------- normalize and write output ----------
    for (int idx = threadIdx.x; idx < channel_size; idx += BLOCK_SIZE) {
        int n = idx / spatial;
        int rem = idx - n * spatial;
        int h = rem / W;
        int w_idx = rem - h * W;
        int offset = ((n * C + c) * H + h) * W + w_idx;
        float val = __half2float(input[offset]);
        float y = (val - mean) * inv_std;   // normalize
        y = y * w + b;                      // affine
        output[offset] = __float2half(y);
    }
}

// -------------------------------------------------------------------------

at::Tensor batchnorm_fp16_forward(
    const at::Tensor& input,
    const at::Tensor& weight,
    const at::Tensor& bias,
    const float eps)
{
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda() && bias.is_cuda(), "weight/bias must be CUDA tensors");
    TORCH_CHECK(input.dtype() == at::kHalf, "input must be float16");
    TORCH_CHECK(weight.dtype() == at::kHalf && bias.dtype() == at::kHalf,
                "weight and bias must be float16");
    TORCH_CHECK(input.dim() == 4, "input must be 4‑D (N, C, H, W)");

    const int N = input.size(0);
    const int C = input.size(1);
    const int H = input.size(2);
    const int W = input.size(3);

    auto output = at::empty_like(input);

    const int threads = 256;                     // BLOCK_SIZE
    const dim3 blocks(C);
    const size_t shmem = threads * sizeof(float);

    AT_DISPATCH_HALF_TYPES_AND_HALF(input.scalar_type(), "batchnorm_fp16_forward", ([&] {
        batchnorm_fp16_forward_kernel<threads><<<blocks, threads, shmem, at::cuda::getCurrentCUDAStream()>>>(
            input.data_ptr<scalar_t>(),
            output.data_ptr<scalar_t>(),
            weight.data_ptr<scalar_t>(),
            bias.data_ptr<scalar_t>(),
            N, C, H, W,
            eps);
    }));

    TORCH_CHECK(cudaGetLastError() == cudaSuccess,
                "CUDA error in batchnorm_fp16_forward_kernel");

    return output;
}

// -------------------------------------------------------------------------

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("forward", &batchnorm_fp16_forward, "BatchNorm2d fp16 forward (CUDA)");
}
'''

# Compile the inline extension
bn_ext = load_inline(name='batchnorm_fp16_ext',
                     cpp_sources='',
                     cuda_sources=src,
                     functions=['forward'],
                     verbose=False)

# -------------------------------------------------------------------------
# PyTorch wrapper module using the custom kernel
# -------------------------------------------------------------------------
class ModelNew(nn.Module):
    """
    Drop‑in replacement for nn.BatchNorm2d using a custom fp16 CUDA kernel.
    Mirrors the default behavior of torch.nn.BatchNorm2d (affine=True,
    track_running_stats=True, momentum=0.1, eps=1e-5).
    """
    def __init__(self, num_features: int, eps: float = 1e-5, momentum: float = 0.1):
        super().__init__()
        self.num_features = num_features
        self.eps = eps
        self.momentum = momentum

        # affine parameters
        self.weight = nn.Parameter(torch.ones(num_features, dtype=torch.float16, device='cuda'))
        self.bias   = nn.Parameter(torch.zeros(num_features, dtype=torch.float16, device='cuda'))

        # running statistics (buffers – not used for the forward output in training)
        self.register_buffer('running_mean', torch.zeros(num_features, dtype=torch.float16, device='cuda'))
        self.register_buffer('running_var',  torch.ones(num_features, dtype=torch.float16, device='cuda'))

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if not x.is_cuda:
            raise RuntimeError('ModelNew only supports CUDA tensors')
        if x.dtype != torch.float16:
            raise RuntimeError('ModelNew only supports float16 tensors')

        if self.training:
            # Compute output using custom kernel (training mode)
            out = bn_ext.forward(x, self.weight, self.bias, self.eps)

            # Update running statistics (mirroring nn.BatchNorm2d)
            with torch.no_grad():
                # compute batch mean & var per channel (same reduction as kernel)
                N, C, H, W = x.shape
                x_reshaped = x.permute(1, 0, 2, 3).contiguous().view(C, -1)   # (C, N*H*W)
                batch_mean = x_reshaped.mean(dim=1, dtype=torch.float32).to(torch.float16)
                batch_var  = x_reshaped.var(dim=1, unbiased=False, dtype=torch.float32).to(torch.float16)

                self.running_mean.mul_(1.0 - self.momentum).add_(batch_mean, alpha=self.momentum)
                self.running_var.mul_(1.0 - self.momentum).add_(batch_var,  alpha=self.momentum)
            return out
        else:
            # Evaluation mode – use stored running stats (same formula as torch.nn.BatchNorm2d)
            # y = (x - running_mean) / sqrt(running_var + eps) * weight + bias
            rm = self.running_mean.view(1, -1, 1, 1).to(torch.float32)
            rv = self.running_var.view(1, -1, 1, 1).to(torch.float32)
            w  = self.weight.view(1, -1, 1, 1).to(torch.float32)
            b  = self.bias.view(1, -1, 1, 1).to(torch.float32)

            x_f32 = x.to(torch.float32)
            y = (x_f32 - rm) * torch.rsqrt(rv + self.eps)
            y = y * w + b
            return y.to(torch.float16)

# -------------------------------------------------------------------------
# Helper functions matching the reference API
# -------------------------------------------------------------------------
def get_inputs():
    # same shape as reference
    batch_size = 64
    features = 64
    dim1 = 512
    dim2 = 512
    x = torch.rand(batch_size, features, dim1, dim2, dtype=torch.float16, device='cuda')
    return [x]

def get_init_inputs():
    # number of features
    return [64]

# -------------------------------------------------------------------------
# Simple sanity check (optional, can be removed in production)
# -------------------------------------------------------------------------
if __name__ == "__main__":
    torch.manual_seed(0)
    model_ref = nn.BatchNorm2d(64).cuda().half()
    model_new = ModelNew(64).cuda().half()
    model_new.weight.data.copy_(model_ref.weight.data)
    model_new.bias.data.copy_(model_ref.bias.data)
    model_new.running_mean.data.copy_(model_ref.running_mean.data)
    model_new.running_var.data.copy_(model_ref.running_var.data)

    x = torch.rand(64, 64, 512, 512, dtype=torch.float16, device='cuda')
    out_ref = model_ref(x)
    out_new = model_new(x)

    print('max diff (training):', (out_ref - out_new).abs().max().item())

    model_ref.eval()
    model_new.eval()
    out_ref_e = model_ref(x)
    out_new_e = model_new(x)
    print('max diff (eval):', (out_ref_e - out_new_e).abs().max().item())
